TP.register({id:"lp3-g2",lp:3,grade:"2",mode:"curriculum",checks:2,nextGrade:"3rd grade",build(E){const F=E.F;const ico=(n,px)=>(F.icon||F.pic2)(n,px)||n;const STORY="On Friday afternoon a strong wind blew. It came across the pumpkin patch. It lifted the old straw hat right off the scarecrow. Jada watched the hat spin over the corn rows. She saw it land in the mud. She ran after it in her rubber boots. The hat was wet and floppy. So she hung it on the fence. It would dry in the sun. Later, Jada climbed onto a hay bale. She put the hat back on the scarecrow’s head. This time she tied it on with a piece of string. “Now you will not lose it again,” she said.";const FABLE="Goat found a bag of sunflower seeds by the fence. Hen had dropped it on her way home. Goat’s tummy growled. “No one saw me find it,” he thought. He looked at the seeds for a long time. Then he walked all the way to Hen’s coop and knocked. “Is this your bag?” he asked. Hen clapped her wings. “Yes! Those seeds are for my chicks.” She poured some into Goat’s hat to say thank you. Goat walked home feeling full and glad, even before he ate a single seed.";const GROW="A pumpkin starts as a flat white seed. Farmers plant the seeds in late spring. By then the soil is warm. In about a week, a green sprout pushes up. Soon long vines spread across the ground. Big yellow flowers open on the vines. After bees visit the flowers, tiny green pumpkins begin to grow. They need lots of sun and water all summer. By fall, the pumpkins have turned orange. Their shells are hard. A farmer cuts the stem and leaves a short handle on top.";const SUNFLOWER="Sunflowers are some of the tallest flowers on a farm. Some grow taller than a grown-up. A young sunflower turns its head during the day to follow the sun across the sky. The big brown middle of the flower is packed with seeds. One flower can hold more than one thousand seeds. In fall, the heavy head droops down. Birds love to snack on the seeds. People eat them too, and some seeds are pressed to make cooking oil.";const WORDS=["patch","corn","leaf","bright","soil","pumpkin","scarecrow","unload","seedless","people","sharb","troid"];const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.5rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const INK=window.TP_ICON_INK||"#6B4A3C";const eye=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const blush=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const smile=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4));const PK_ART=`<path d="M-7 -27 L-5 -45 q0 -5 6 -5 q6 0 6 5 L9 -26 Z" fill="#B08E63" stroke="${INK}" stroke-width="3.4"/><path d="M-7 -34 q-15 -7 -18 3 q13 7 18 -3 Z" fill="#A8D49A" stroke="#4E7A46" stroke-width="3"/><ellipse cx="0" cy="0" rx="44" ry="33" fill="#F7A657" stroke="${INK}" stroke-width="3.4"/><path d="M-8 -31 C-36 -21 -36 21 -8 31 M8 -31 C36 -21 36 21 8 31" fill="none" stroke="#DD8437" stroke-width="2.6"/>`+FACE(0,-3,15,5);const pump=(cx,cy)=>`<g transform="translate(${cx},${cy+4}) scale(.5455)" stroke-linejoin="round" stroke-linecap="round">${PK_ART}</g>`;function pumpArray(rows,cols){const c=62;let s=`<svg viewBox="0 0 ${cols*c+12} ${rows*c+12}" width="${cols*c+12}" role="img" aria-label="${rows} rows of ${cols} pumpkins">`;for(let r=0;r<rows;r++)for(let k=0;k<cols;k++)s+=pump(6+k*c+c/2,6+r*c+c/2+4);return s+"</svg>"}const GCATS=["Pumpkins","Corn","Squash","Hay"];let bars=[0,0,0,0];function wagonGraph(){const cell=36,x0=70,y0=44,rows=8,colW=100,W=x0+GCATS.length*colW+20,H=y0+rows*cell+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%" role="img" aria-label="Bar graph to fill in">`;s+=`<text x="${x0+GCATS.length*colW/2}" y="22" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" font-size="22" fill="var(--ink)">Wagon Loads This Week</text>`;for(let r=0;r<=rows;r++){const y=y0+(rows-r)*cell;s+=`<line x1="${x0}" y1="${y}" x2="${x0+GCATS.length*colW}" y2="${y}" stroke="var(--line)" stroke-width="2"/><text x="${x0-12}" y="${y}" text-anchor="end" dominant-baseline="central" font-size="18" fill="var(--ink)">${r}</text>`}GCATS.forEach((c,i)=>{const bx=x0+i*colW+20;for(let r=0;r<rows;r++){const y=y0+(rows-r-1)*cell,on=r<bars[i];s+=`<rect class="bc" data-c="${i}" data-r="${r+1}" x="${bx}" y="${y}" width="60" height="${cell}" fill="${on?"var(--sea)":"transparent"}" stroke="var(--sea)" stroke-dasharray="${on?"0":"4 4"}" stroke-width="2" style="cursor:pointer"/>`}s+=`<text x="${bx+30}" y="${y0+rows*cell+26}" text-anchor="middle" font-size="18" font-weight="700" fill="var(--ink)">${c}</text>`});return s+"</svg>"}const bigTable=(cap,head,rows)=>`<div class="tool-scroll" style="margin:6px 0 12px"><table class="chart" style="margin:0 auto;font-size:1.35rem"><caption style="font-family:var(--font-display);font-weight:700;font-size:1.4rem;padding-bottom:6px;white-space:nowrap">${cap}</caption><tr>${head.map(h=>`<th style="text-align:center">${h}</th>`).join("")}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</table></div>`;const WAGON_TABLE=bigTable("Loads the Wagon Carried",["Crop","Loads"],[["Pumpkins","7"],["Corn","4"],["Squash","6"],["Hay","2"]]);const SIGN=`<div style="max-width:600px;margin:8px auto 18px;border:4px solid var(--gold-ink);border-radius:14px;background:var(--surface);padding:14px 24px;font-size:1.4rem;line-height:1.6"><p style="text-align:center;font-weight:700;font-size:1.6rem;margin:0 0 6px">${ico("sunflower",26)} Harvest Hill Pumpkin Patch ${ico("sunflower",26)}</p><ul style="margin:0"><li>Open on Saturday and Sunday</li><li>Wagon rides start every hour</li><li>Small pumpkins cost 2 dollars</li><li>Big pumpkins cost 5 dollars</li><li>Wear boots. The field is muddy.</li></ul></div>`;function pumpRow(n){const c=62;let s=`<svg viewBox="0 0 ${n*c+12} ${c+12}" width="${n*c+12}" role="img" aria-label="A row of ${n} pumpkins">`;for(let k=0;k<n;k++)s+=pump(6+k*c+c/2,6+c/2+4);return s+"</svg>"}function shapeSet(){const pent=[[50,10],[92.8,41.1],[76.5,91.4],[23.5,91.4],[7.2,41.1]];const hex=[[95,50],[72.5,89],[27.5,89],[5,50],[27.5,11],[72.5,11]];return F.row([F.poly(pent,{size:170,alt:"A five sided shape"}),"1"],[F.poly(hex,{size:170,alt:"A six sided shape",fill:"var(--gold)"}),"2"],[F.prism(1,1,1,{unit:90}),"3"])}const STOPS=[{id:1,title:"Corn Row Words",short:"Corn Words",parts:[{std:["RF.2.3"],kind:"words",wordPics:3,words:WORDS,n:12,dur:80,dir:"Read each word out loud. The last two are silly words. Just sound them out.",desc:"reading words with vowel teams, r-controlled vowels, two syllables, a prefix, a suffix, and an irregular spelling",key:["Read each word. sharb and troid are silly words: listen for the ar sound and the oi sound.","Watch for: tch and r-controlled vowels (patch, corn), vowel teams (leaf, bright, soil), two syllables (pumpkin, scarecrow), a prefix and a suffix (unload, seedless), an irregular word (people)."]}]},{id:2,title:"Pumpkin Rows",parts:[{std:["2.OA.C.4"],dur:130,dir:"Look at the rows. Say how many in all. Write your adding sentences on your paper and hold them up.",desc:"finding the total of arrays up to 5 by 5 and writing it as a sum of equal addends",fig:()=>F.row([pumpArray(2,5),"Pumpkins"],[F.array(3,4,"sunflower"),"Sunflowers"],[F.array(4,5,"corn"),"Corn"]),qs:["How many pumpkins in all? Write an adding sentence for the rows.","How many sunflowers in all? Write an adding sentence for the rows.","How many ears of corn in all? Write an adding sentence for the rows.","Spot the mistake. A farmer stacked 3 rows of 3 hay bales. She wrote 3 + 3 = 6. What did she forget? Fix it.","A patch has 5 rows with 5 pumpkins in each row. Draw dots to show it. How many pumpkins? Write the adding sentence."],key:["10 pumpkins. 5 + 5 = 10 (also correct: 2 + 2 + 2 + 2 + 2 = 10)","12 sunflowers. 4 + 4 + 4 = 12 (also correct: 3 + 3 + 3 + 3 = 12)","20 ears of corn. 5 + 5 + 5 + 5 = 20 (also correct: 4 + 4 + 4 + 4 + 4 = 20)","She forgot one row. 3 + 3 + 3 = 9","25 pumpkins. 5 + 5 + 5 + 5 + 5 = 25. The drawing has 5 rows of 5."]}]},{id:3,title:"The Scarecrow’s Hat",short:"Scarecrow Hat",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:97,label:"words read correctly",dur:120,dir:"Read the story out loud. Use your best reading voice.",desc:"a 97-word grade-level story read aloud",html:()=>`<p class="passage g2-fluency">${STORY}</p>`,supfig:()=>`<div style="text-align:center;margin:10px 0"><img alt="Six picture panels that tell the story. A strong wind blows over the pumpkin patch. The wind lifts the straw hat off the scarecrow. Jada watches the hat spin over the corn rows. The hat lands in the mud and Jada runs after it in rubber boots. The wet hat hangs on the fence to dry in the sun. Jada climbs a hay bale and ties the hat back on the scarecrow with string." src="data:image/webp;base64,${window.TP_IMG1.wp3.hatstory}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,key:["97 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]},{title:"Story Questions",std:["RL.2.1"],dur:95,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering when, where, why, how, and what questions about a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Scarecrow’s Hat (click to open or close the story)</summary><p class="passage" style="font-size:1.5rem;line-height:1.65;max-width:none">${STORY}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-fluency"))d.open=false},qs:["When did the wind blow across the pumpkin patch?","Where did the hat land?","Why did Jada hang the hat on the fence?","How did Jada reach the top of the scarecrow?","What did Jada do so the hat would stay on?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["On Friday, in the afternoon","In the mud (past the corn rows)","It was wet and floppy. She wanted the sun to dry it.","She stood on a hay bale.","She tied the hat on with string.","Asks a question that is about this story and starts with a question word (for example: Who put the hat back? Why did the hat blow off?)."]}]},{id:4,title:"Seed Packet Numbers",short:"Seed Packets",parts:[{title:"Hundreds, Tens, Ones",std:["2.NBT.A.1"],dur:85,dir:"A farmer counts seeds with blocks. Answer out loud. Write number 4 on your paper and hold it up.",desc:"telling what the digits of a three-digit number stand for (hundreds, tens, and ones)",fig:()=>F.row(F.blocks(2,4,3)),qs:["What number do the blocks show?","Think about the number 586. What is the 8 worth?","How many tens make 100?","Write the number that has 6 hundreds, 0 tens, and 9 ones.","True or silly? In 372, the 3 is worth 30."],key:["243 (2 hundreds, 4 tens, 3 ones)","80, or 8 tens","10 tens","609","Silly. The 3 is worth 300, or 3 hundreds."]},{title:"Name That Number",std:["2.NBT.A.3"],dur:75,dir:"Say the first answer out loud. Write the others on your paper and hold them up.",desc:"reading and writing numbers to 1000 as numerals, number names, and expanded form",qs:["Read this number out loud: <b>417</b>","Write this number with digits: <b>five hundred eight</b>","Write <b>362</b> in expanded form.","What number is <b>200 + 9</b>? Write it."],key:["four hundred seventeen","508 (watch for 58 or 5008)","300 + 60 + 2","209 (watch for 29)"]}]},{id:5,title:"Barn Door Tale",short:"Barn Tale",parts:[{std:["RL.2.2"],dur:140,dir:"Read the fable. Then tell it back in your own words and answer out loud.",desc:"retelling a fable in order and telling its lesson",html:()=>passage("Goat and the Bag of Seeds",FABLE),supfig:()=>`<div style="text-align:center;margin:10px 0"><img alt="Nine picture panels that tell the story. Goat finds a bag of sunflower seeds by the fence. Hen dropped it on her way home. Goat is hungry and thinks no one saw him find it. He looks at the seeds for a long time. He walks to Hen's coop and knocks. He asks if the bag is hers. Hen claps her wings and says the seeds are for her chicks. She pours some into Goat's hat to say thank you. Goat walks home feeling full and glad." src="data:image/webp;base64,${window.TP_IMG1.wp3.barnstory}" style="width:760px;max-width:100%;height:auto;border-radius:16px"></div>`,qs:["Tell what happened at the beginning of the story.","Tell what Goat did next.","Tell how the story ended.","What lesson does this story teach?"],key:["Goat found a bag of sunflower seeds that Hen had dropped. He was hungry, and nobody saw him find it.","He thought about it for a long time. Then he took the bag to the coop and asked Hen if it was hers.","Hen was happy because the seeds were for her chicks. She gave Goat some seeds to thank him, and he went home feeling glad.","Be honest. Do the right thing even when no one is watching. (Also accept: give back what is not yours, or doing the right thing feels good.)"]}]},{id:6,title:"Harvest Wagon Problems",short:"Wagon Math",parts:[{std:["2.OA.A.1"],dur:170,dir:"Read each problem with your teacher. Solve it on your paper. You can draw or write a number sentence. Say your answer.",desc:"one-step and two-step addition and subtraction word problems within 100 with the unknown in different places",qs:["A wagon holds 30 pumpkins. 18 are orange. The rest are white. How many pumpkins are white?","Tess picked 26 ears of corn. Luis picked 17 more ears than Tess. How many ears did Luis pick?","Some sunflowers were in a bucket. A farmer sold 25 of them. Now 38 sunflowers are left. How many sunflowers were in the bucket at first?","This one has two steps. A farmer had 45 pumpkins. She sold 19 in the morning. Then she picked 30 more. How many pumpkins does she have now?"],key:["12 white pumpkins (18 + □ = 30, or 30 - 18 = 12)","43 ears of corn (26 + 17 = 43)","63 sunflowers (□ - 25 = 38, or 38 + 25 = 63)","56 pumpkins (45 - 19 = 26, then 26 + 30 = 56)"]}]},{id:7,title:"Scarecrow’s Notebook",short:"Write",parts:[{alt:{group:"write",key:"story",label:"Lost and Found",icon:"🔑",hint:"Tell a story about something lost or found"},std:["W.2.3"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"a short narrative with events in order, details, time words, and an ending",html:()=>`<p class="big">Write a story about a time you lost something or found something. It can be real or made up. Tell what happened in order. Tell what you did and how you felt. Write 4 sentences.</p>${pills("First","Then","After that","In the end")}`,key:["Tells about one event or a short set of events in order","Includes details about actions, thoughts, or feelings","Uses time words like first, then, after that, or in the end","Ends with a sentence that wraps up the story"]},{alt:{group:"write",key:"facts",label:"All About Fall",icon:"🍂",hint:"Teach a friend about fall"},std:["W.2.2"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"a short informative piece with a topic sentence, facts, and a closing",supfig:()=>`<div style="text-align:center;margin:10px 0"><img alt="Four fall pictures. Colorful leaves falling from a tree. A cold thermometer and a frost sign over frosty grass. A basket of red apples under an apple tree. A big pumpkin and a small pumpkin growing on the vine." src="data:image/webp;base64,${window.TP_IMG1.wp3.fallpics}" style="width:620px;max-width:100%;height:auto;border-radius:16px"></div>`,html:()=>`<p class="big">Write to teach a friend about fall. Start by telling what you are writing about. Give 2 or more facts. End with a closing sentence. Write 4 sentences.</p><div class="passage sm" style="margin-top:14px"><b>Facts you can use</b><ul style="margin:6px 0 0"><li>In fall, the air gets cooler.</li><li>Leaves change color and drop from the trees.</li><li>The days get shorter.</li><li>Harvest means picking crops when they are ready.</li></ul></div>`,key:["Starts with a sentence that names the topic (fall)","Gives 2 or more facts about fall","The facts are true and stay on the topic (telling what a word like harvest means counts as a fact)","Ends with a closing sentence"]}]},{id:8,title:"Hay Bale Count",short:"Hay Count",parts:[{std:["2.NBT.A.2"],dur:70,dir:"Count out loud.",desc:"skip-counting by 5s, 10s, and 100s and counting past 500",qs:["Skip count by 5s from 85 to 120.","Skip count by 10s from 275 to 335.","Count by ones from 496 to 503.","Skip count by 100s from 150 to 750."],key:["85, 90, 95, 100, 105, 110, 115, 120. Watch the jump past 100.","275, 285, 295, 305, 315, 325, 335. Watch the jump past 295.","496, 497, 498, 499, 500, 501, 502, 503. Watch the jump past 499.","150, 250, 350, 450, 550, 650, 750"]}]},{id:9,title:"From Seed to Pumpkin",short:"Seed to Pumpkin",parts:[{std:["RI.2.1"],dur:130,dir:"Read about pumpkins. Then answer each question out loud.",desc:"asking and answering what, when, and how questions about an informational text the student read",html:()=>passage("How a Pumpkin Grows",GROW),qs:["What does a pumpkin seed look like?","When do farmers plant pumpkin seeds?","What happens after bees visit the flowers?","How can you tell that a pumpkin is ready to pick in fall?","Your turn. Ask a question about pumpkins. Start with who, what, where, when, why, or how."],key:["Flat and white","Late spring (when the soil is warm)","Tiny green pumpkins start to grow.","It is orange and its shell is hard.","Asks a question that is about the topic and starts with a question word (for example: How long does a pumpkin take to grow? Why do pumpkins need bees?)."]}]},{id:10,title:"Wagon Load Graph",short:"Wagon Graph",parts:[{std:["2.MD.D.10"],dur:150,dir:"Use the table. Tell your teacher how tall to make each bar. Then answer the questions out loud.",desc:"making a bar graph with four categories from a table and solving compare and put-together problems from it",render:()=>`<div class="figure" style="align-items:center;gap:36px">${WAGON_TABLE}${wagonGraph()}</div>`,bind:(root,ctx)=>root.querySelectorAll(".bc").forEach(r=>r.onclick=()=>{const c=+r.dataset.c,v=+r.dataset.r;bars[c]=bars[c]===v?v-1:v;ctx.redraw()}),printHtml:()=>`${WAGON_TABLE}<p class="small">An empty bar graph with a bar for Pumpkins, Corn, Squash, and Hay. You click the squares to build each bar as the student tells you.</p>`,qs:["Build the bar graph. Tell your teacher where each bar should stop.","How many more loads of pumpkins than loads of corn?","How many loads of corn and squash in all?","How many fewer loads of hay than loads of squash?","How many loads were there in all this week?"],key:["Bars stop at Pumpkins 7, Corn 4, Squash 6, Hay 2. Click the squares the student says. If a bar is wrong, ask the student to check the table before you fix it.","3 more (7 - 4 = 3)","10 loads (4 + 6 = 10)","4 fewer (6 - 2 = 4)","19 loads (7 + 4 + 6 + 2 = 19)"]}]},{id:11,title:"Look at the Patch Sign",short:"Patch Sign",parts:[{std:["W.2.8"],dur:110,read:"Harvest Hill Pumpkin Patch. Open on Saturday and Sunday. Wagon rides start every hour. Small pumpkins cost 2 dollars. Big pumpkins cost 5 dollars. Wear boots. The field is muddy.",dir:"Listen while your teacher reads the sign. Then say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a sign and recalling an experience to answer questions",fig:()=>SIGN,qs:["A friend asks, “When is the patch open?” Use the sign to tell them.","Why should you wear boots to the patch?","Write one sentence that tells a friend how much the pumpkins cost.","Now use what you remember. Think of a fall day. What is one thing you saw, heard, or felt outside? Say it in a sentence."],key:["On Saturday and on Sunday (the weekend)","Because of the mud. The sign says the field is muddy.","The sentence gives both prices from the sign (for example: Small pumpkins cost 2 dollars and big pumpkins cost 5 dollars.).","Tells one detail remembered from a real fall day, in a sentence that answers the question (for example: I heard leaves crunch under my shoes.)."]}]},{id:12,title:"Measure the Harvest",short:"Measure",parts:[{std:["2.MD.A.1"],dur:95,dir:"Answer out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring length with a ruler and choosing the right measuring tool",fig:()=>F.row(F.ruler({length:8,unit:"inches",item:6,itemLabel:"ear of corn"})),qs:["Look at the ruler. How long is the ear of corn?","A sunflower is taller than you. Which tool is better for measuring it: a ruler or a yardstick?","You want to measure around a fat, round pumpkin. Would you use a ruler or a measuring tape? Why?","Get a ruler. Measure your pencil or a crayon. How long is it?"],key:["6 inches","A yardstick. A sunflower is much longer than a ruler. (A measuring tape or a meter stick is also a good choice.)","A measuring tape, because it bends around the pumpkin.","Lines up one end at 0, reads the nearest whole inch or centimeter, and says the unit."]}]},{id:13,title:"Sunflower Chat",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:90,read:SUNFLOWER,dir:"Listen first. Then answer your teacher’s questions out loud.",desc:"describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ico("sunflower",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about sunflowers.</p>`,key:["Ask: “What does a young sunflower do during the day?” (turns its head to follow the sun)","Ask: “Where are the seeds on a sunflower?” (in the big brown middle of the flower)","Ask: “Who eats sunflower seeds?” (birds and people; listen for both)","Say: “Tell me two more things you learned about sunflowers.” (any two: they are some of the tallest flowers on a farm, some grow taller than a grown-up, one flower can hold more than one thousand seeds, the heavy head droops in fall, some seeds are pressed to make cooking oil)"]},{title:"Tell Me a Story",std:["SL.2.4"],n:4,label:"checks met",dur:70,dir:"Tell your story out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you got muddy, wet, or messy. Where were you? How did it happen? What did you do next?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit the story (where, when, who, or what)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:14,title:"Fix the Scarecrow’s Note",short:"Fix the Note",parts:[{title:"Say It Right",std:["L.2.1"],dur:70,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, putting words in order)",qs:["Today the pumpkins grow. Last summer the pumpkins ____.","One goose, two ____.","The kids carried the pumpkins all by ____.","Which word fits? The wagon rolled ____ down the hill. Is it slow or slowly?","Mix-up! Put these words in order to make a sentence: <b>of hay / the wagon / full / is</b>"],key:["grew","geese","themselves","slowly","The wagon is full of hay."]},{title:"Write It Right",std:["L.2.2"],dur:85,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in a place name, an apostrophe to show who owns something, a comma in a letter closing, spelling a vowel team word)",qs:["Fix this sentence: <b>the pumpkin patch is near lake tahoe</b>","The hat belongs to the farmer. Write the missing word: <b>the ____ hat</b>","This is the end of a letter. Write it and add the missing mark: <b>Your friend</b>","Listen. Write the word your teacher says."],key:["The pumpkin patch is near Lake Tahoe. (capital T at the start, capital L and T in Lake Tahoe, and a period)","farmer’s (apostrophe before the s)","Your friend, (comma after friend)","Say: “Road. The wagon went down the road.” The student writes road (oa)."]}]},{id:15,title:"Which Pumpkin Wins",short:"Opinion",parts:[{alt:{group:"opinionWrite",key:"opinion",label:"Which Pumpkin Wins"},std:["W.2.1"],n:3,label:"checks met",dur:60,dir:WRITE_DIR,desc:"a short opinion piece with a reason and a closing",html:()=>`<p class="big">Harvest Hill sells small pumpkins and big pumpkins. Which one is the better buy?</p><p class="big">Write 3 sentences. Say which one you think is better, give one reason, and end it.</p>`,key:["Opens by naming what the writing is about and states an opinion, such as: The small pumpkin is the better buy.","Gives at least one reason that goes with the opinion, such as: it is easier to carry, or you can buy two for the price of one big one.","Ends with a closing sentence, such as: That is why I would buy the small one. One short line counts.","The reason does not have to be the one you would give. It has to connect to the opinion."]}]},{id:16,title:"Seed Barn Numbers",short:"Barn Numbers",parts:[{title:"Odd or Even",std:["2.OA.C.3"],n:3,dur:50,dir:"Look at the two rows. Answer out loud. Write the last answer on your paper.",fig:()=>F.row([pumpRow(13),"Row A"],[pumpRow(8),"Row B"]),qs:["Row A: is the number of pumpkins odd or even? How do you know?","Row B: odd or even? How do you know?","Write an equation that shows the number in Row B as two equal addends."],key:["13, odd. Pairing them up leaves one over, or counting by twos does not land on 13.","8, even. Every pumpkin has a partner, or counting by twos lands on 8.","4 + 4 = 8"],desc:"telling odd from even and writing an even number as a sum of two equal addends"},{title:"Three Digit Loads",std:["2.NBT.B.7"],n:3,dur:60,dir:"Solve on your paper. Tell your teacher the answer and how you got it.",qs:["Last fall the patch sold 345 pumpkins. This fall it sold 128. How many is that in all?","The barn had 406 seed packets. The patch sold 172 of them. How many packets are left?","In 345 + 128, what happened when you added the ones? Tell me why."],key:["473 (345 + 128)","234 (406 - 172)","8 ones plus 5 ones is 13 ones, which is 1 ten and 3 ones, so the ten goes over to the tens place and a 3 stays in the ones place."],desc:"adding and subtracting within 1000 with regrouping, and explaining the regrouping"}]},{id:17,title:"At the Patch Gate",short:"Gate",parts:[{title:"What Time",std:["2.MD.C.7"],n:3,dur:50,dir:"Look at the clocks. Say each time. Then write the last answer on your paper.",fig:()=>F.row([F.clock(10,20,190),"A"],[F.clock(1,45,190),"B"]),qs:["Clock A: what time is it?","Clock B: what time is it?","The patch opens at 9:30 in the morning and closes at 5:00 in the afternoon. Write both times with a.m. or p.m."],key:["10:20, or twenty past ten","1:45, or quarter to two, or forty-five past one","9:30 a.m. and 5:00 p.m."],desc:"telling time to five minutes and writing times with a.m. and p.m."},{title:"Count the Money",std:["2.MD.C.8"],n:2,dur:50,dir:"Look at the coins. Answer out loud.",fig:()=>F.coins(["Q","Q","D","D","D","P","P","P","P"]),fig2:()=>F.row(F.bill(5)),qs:["How much money is here? Use the cents sign when you write it.","The sign says a small pumpkin costs 2 dollars. You pay with this 5 dollar bill. How much change do you get back?"],key:["84¢ (2 quarters is 50¢, 3 dimes is 30¢, 4 pennies is 4¢: 50 + 30 + 4 = 84)","$3 (5 - 2 = 3)"],desc:"finding the value of a group of coins and solving a money problem with dollars"}]},{id:18,title:"Shapes in the Barn",short:"Shapes",parts:[{std:["2.G.A.1"],n:4,dur:50,dir:"Look at the three shapes. Answer out loud. Then draw on your paper.",fig:()=>shapeSet(),qs:["Shape 1: how many sides does it have? What is it called?","Shape 2: how many sides does it have? What is it called?","Shape 3 is a solid shape. What is it called, and how many faces does it have?","Draw a quadrilateral that is not a square. Hold it up."],key:["5 sides and 5 angles. It is a pentagon.","6 sides and 6 angles. It is a hexagon.","A cube. It has 6 faces, and every face is the same size square.","Any closed shape with 4 straight sides that is not a square, such as a rectangle, a rhombus, or a trapezoid. It does not have to be neat."],desc:"naming shapes by their number of sides and faces, and drawing a quadrilateral"}]},{id:19,title:"Three Pumpkin Seedlings",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">Three pumpkin seedlings were started in cups in the barn and checked after three weeks.</p>
     <table class="bigTable"><tr><th>Cup</th><th>What it got</th><th>How it looked after three weeks</th></tr>
     <tr><td>1</td><td>water, no sunlight (back of the barn)</td><td>long, floppy, almost white</td></tr>
     <tr><td>2</td><td>sunlight and water (barn window)</td><td>short, thick, dark green, 5 leaves</td></tr>
     <tr><td>3</td><td>sunlight, no water (barn window)</td><td>shrivelled, 2 brown leaves</td></tr></table>
     <div class="figure">${ico("sprout",88)}${ico("pumpkin",88)}</div>`,qs:["Which cup grew into the healthiest seedling, and what did it get?","Cup 1 was watered every single day. Why did it turn almost white?","You want to test only whether a seedling needs sunlight. Name two things you would keep the same, and name the one thing you would change."],key:["Cup 2. It got both sunlight and water.","It was kept at the back of the barn with no sunlight. Water on its own is not enough. A plant needs sunlight to make its food and to go green.","Keep the same: the same soil, the same cup, the same number of seeds, the same amount of water, the same room. Change only one thing: one cup in the window and one cup in the dark. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves seeds",html:()=>`<p class="big">A squirrel picks up seeds. They are at the edge of the patch. It carries them off. It buries them in the soft dirt. It never comes back for some. Some of the buried ones stay. Those ones grow.</p>
     <div class="figure">${ico("squirrel",88)}${ico("acorn",88)}</div>
     <p class="big">Draw a model you could really build out of things in a barn, such as a spoon taped to a stick or a paper cup, that would pick a seed up, carry it, and put it under the dirt.</p>`,qs:["Draw your model. Label the part that holds the seed and the part that puts it under the dirt.","Which animal job does your model copy, and why does burying the seed matter to the plant?"],key:["Any model with a holding part and a digging or dropping part: a spoon on a stick, a cup with a hole, a scoop with a flap, tongs and a trowel. The two labeled parts are what to look for.","It copies an animal that carries seeds away and buries them. Burying matters because the seed is in the soil where it can get water and grow, instead of lying on top where it dries out or gets eaten."]}]},{id:20,title:"The Pond and the Hay Field",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Two children looked for living things in two places at the farm, for twenty minutes in each place.</p>
     <table class="bigTable"><tr><th>The pond at the edge of the patch</th><th>The dry hay field</th></tr>
     <tr><td>2 kinds of frog</td><td>1 kind of dry grass</td></tr>
     <tr><td>3 kinds of water plant</td><td>2 kinds of grasshopper</td></tr>
     <tr><td>1 kind of water beetle</td><td>1 field mouse hole</td></tr>
     <tr><td>1 duck, 1 dragonfly</td><td>1 hawk overhead</td></tr></table>
     <div class="figure">${ico("frog",80)}${ico("wheat",80)}</div>`,qs:["How many kinds of living things are on the pond list?","Name one living thing from the pond list that could not live in the hay field, and say why.","Both lists come from the same farm. Why are the two lists so different?"],key:["8. Two frogs, three water plants, one water beetle, one duck and one dragonfly.","Any sensible pick with a reason: a frog would dry out in the hay field because its skin has to stay wet, a water plant needs its roots in water, a water beetle swims and there is no water to swim in.","Because the two places give different things. One has water all the time, the other is dry with tall grass. Living things live where they can get what they need."]}]},{id:21,title:"One Afternoon, or Thousands of Years",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about the land around the patch, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>a photograph with a date written on the back</td><td>One cloudburst in August cut a channel across the corner of the field in a single afternoon.</td></tr>
     <tr><td>a museum card beside a huge rock</td><td>Ice carried this rock here from far away and then the hills around it slowly wore down over thousands of years.</td></tr></table>`,qs:["Which note tells about a change to the land that happened quickly?","Which note tells about a change that took thousands of years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The photograph with the date, the channel cut in a single afternoon.","The museum card, the hills wearing down over thousands of years.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a stream cutting a valley, a cliff wearing back, soil building up. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">Water turns up in more places on this farm than you would think.</p>
     <div class="figure">${ico("drop",80)}${ico("rain",80)}${ico("snowflake",80)}</div>`,qs:["Name three places on this farm or nearby where you would find water.","Most of the water on Earth is in the ocean and it is salty. Name a place where the water is fresh instead.","Hail that comes down in a storm is water. Is hail solid or liquid? Is the water in the pond solid or liquid?"],key:["Any three: the pond, the well, the creek, the trough, the rain barrel, rain in the clouds, dew or frost on the grass, under the ground, inside the pumpkins.","A pond, a creek, a well, a river, a lake, rain. Fresh water is the kind people and animals can drink.","Hail is solid. The water in the pond is liquid."]}]},{id:22,title:"Holding the Field, and a Map of It",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things put in place to stop wind from changing the shape of the land",html:()=>`<p class="big">After harvest, dry wind lifts the loose soil off the big field and carries it away. Two ways of stopping it were tried, and the soil that blew into a ditch at the far side was measured.</p>
     <table class="bigTable"><tr><th>What was on the field</th><th>Soil blown into the ditch in two weeks</th></tr>
     <tr><td>bare, raked smooth</td><td>12 buckets</td></tr>
     <tr><td>the old corn stalks left standing</td><td>2 buckets</td></tr>
     <tr><td>a row of young pine trees along the windy side</td><td>6 buckets</td></tr></table>`,qs:["Which one kept the most soil on the field?","How do you know, using the numbers in the chart?","The pine trees are small now and will be tall in ten years. Why might the farm keep them anyway?"],key:["leaving the old corn stalks standing","Only 2 buckets blew away with the stalks standing, 6 buckets blew away with the young pines, and 12 buckets blew away off the bare field. The reason must come from the numbers.","Because when the pines are tall they will block much more wind, and they stay there every year without having to be done again. Any reason about the trees getting better over time counts."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the land around the patch. Put in the hill behind the barn, the flat bottom field, the creek, and the pond. Add a key that says which is which.</p>
     <div class="figure">${ico("mountain",88)}${ico("map",88)}${ico("pumpkin",88)}</div>`,qs:["Draw your model map with the hill, the flat field, the creek and the pond on it.","Show me your key. Which parts are land and which parts are water?","Water runs downhill. Looking at your own map, which way would rain on the hill run?"],key:["All four on the page and told apart by shape or color: the hill as a bump or as rings, the flat field left flat, the creek as a line, the pond as a closed shape.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","Down off the hill towards whatever is lowest on their map, usually the creek or the pond. The answer has to match their own drawing, so follow their finger."]}]},{id:23,title:"Sorting the Barn Shelf",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things off the barn shelf, and what was noticed about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What was noticed</th></tr>
     <tr><td>a seed pail</td><td>metal</td><td>hard, shiny, cold, holds water</td></tr>
     <tr><td>a feed sack</td><td>burlap cloth</td><td>rough, bends easily, water runs through it</td></tr>
     <tr><td>a jam jar</td><td>glass</td><td>hard, smooth, you can see through it</td></tr>
     <tr><td>a boot</td><td>rubber</td><td>bends, stretches a little, holds water</td></tr></table>`,qs:["Sort the four items into a group that holds water and a group that water runs through.","Which two items are hard? Which two bend?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Holds water: the metal pail, the glass jar, the rubber boot. Water runs through: the burlap sack.","Hard: the metal pail and the glass jar. Bend: the burlap sack and the rubber boot.","Any property that can be seen or felt and that really splits the four: rough or smooth, shiny or dull, see through or not, stretches or does not. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The scarecrow at the end of the rows needs a new coat. Three materials were pinned out in the field through a week of wind and rain.</p>
     <table class="bigTable"><tr><th>Material</th><th>Still dry underneath</th><th>Torn by the wind after a week</th></tr>
     <tr><td>newspaper</td><td>no</td><td>yes, in pieces</td></tr>
     <tr><td>cotton sheet</td><td>no</td><td>no</td></tr>
     <tr><td>oiled canvas</td><td>yes</td><td>no</td></tr></table>`,qs:["Which material should the scarecrow's coat be made of?","Which two pieces of the chart make you sure?","The cotton sheet did not tear. Why is it still not the right choice?"],key:["the oiled canvas","It was still dry underneath and it was not torn by the wind after a week. Both columns have to be used, not just one.","It let the rain through, so the straw inside would get soaked even though the cloth itself held together. A coat has to keep the wet out as well as stay whole."]}]},{id:24,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">A hay feeder is in the barn. It is made of 10 flat slats. It has 4 corner posts. Screws hold it together. They are held with screws. The screws were taken out. The pieces were stacked by the door.</p>
     <div class="figure">${ico("board",88)}${ico("box",88)}</div>`,qs:["The feeder is gone. Are the slats and posts gone too? What is stacked by the door?","Build something new in your head out of those 10 slats and 4 posts. What is it, and how do the pieces go together?"],key:["No. All 10 slats and all 4 posts are still there, and the screws. They are the same pieces, just not screwed together as a feeder any more.","Any real thing from 10 slats and 4 posts: a bench, a small table, a gate, a crate, a bookshelf, a frame for a seed bed. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the farmhouse on the same cold morning.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A pail of water left out overnight was a solid block of ice by morning.</td></tr>
     <tr><td>Pumpkin seeds roasted in a hot oven turned brown, hard and nutty.</td></tr></table>
     <div class="figure">${ico("pan",80)}${ico("snowflake",80)}</div>`,qs:["Bring the pail of ice into the warm kitchen. What happens to it?","Put the roasted seeds back out in the cold. Do they turn back into soft pale seeds?","Which of the two changes can be undone, and what is your evidence?"],key:["It melts back into water. Warming undoes the freezing.","No. They stay brown, hard and nutty. Cold does not bring the soft pale seeds back.","The water and ice change can be undone. The evidence is that the ice melts back into water when it is warmed, and the roasted seeds do not change back when they are cooled. Listen for the student using what happened, not just saying yes or no."]}]},{id:25,title:"The Rolling Pumpkins",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The pumpkins ride to the barn. They ride in a flat wagon bed. It has no sides. The track between the rows is bumpy. On every bump the pumpkins roll about. They knock into each other. A few end up over the edge. The children walk behind picking them up.</p>`,qs:["What is the problem the children want to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The pumpkins roll around in the wagon bed on the bumps and fall off the edge. Naming the rolling, not the walking behind, is the problem.","Any real question: how many pumpkins fit in the wagon, how big are they, how bumpy is the track, how fast does the wagon go, how high would a side need to be. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would keep the pumpkins still in the wagon bed. Think hard about its shape.</p>
     <div class="figure">${ico("box",88)}${ico("pumpkin",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew stops the pumpkins rolling."],key:["Any design that could really hold pumpkins: sides or a rail around the wagon bed, a tray of round dips or rings, straw packed between them, crates that each hold one, a net over the top.","The shape is the part being checked. Something like: a round dip holds a round pumpkin so it cannot roll, the sides stop it going over the edge, the straw fills the gaps so nothing can move."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both fixes were tried over the same bumpy track, with 20 pumpkins each time.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Pumpkins that fell off</th><th>Pumpkins with a new dent</th></tr>
     <tr><td>a tray with 20 round dips</td><td>0</td><td>1</td></tr>
     <tr><td>a low rail around the edge</td><td>2</td><td>7</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the tray with 20 round dips","No pumpkins fell off with the tray and only 1 was dented, while 2 fell off the railed wagon and 7 were dented. Both columns have to be used, not just the falling off."]}]},{id:26,title:"Farming Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the notice board by the barn door.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>When this farm was new, two oxen pulled the plow and it took a week to turn one field.</td></tr>
     <tr><td>2</td><td>This morning the tractor turned the same field in two hours.</td></tr>
     <tr><td>3</td><td>Long before there were ice houses, farmers here had to dry or salt food to keep it.</td></tr>
     <tr><td>4</td><td>Yesterday the children loaded 60 pumpkins onto the wagon.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about the way it is done now."],key:["Lines 1 and 3, the oxen and the plow, and drying or salting food.","Lines 2 and 4, the tractor this morning and loading the wagon yesterday.","Either one: a tractor does in two hours what oxen took a week to do; now food is kept cold in a refrigerator or a freezer instead of being dried or salted."]}]},{id:27,title:"Where Things Are in the Patch",short:"Patch Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The patch and the fields around it, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ico("corn",46)} corn rows</td><td>${ico("tree",46)} walnut trees</td><td>${ico("wheat",46)} hay field</td></tr>
     <tr><th>B</th><td>${ico("pumpkin",46)} pumpkin patch</td><td>${ico("scarecrow",46)} scarecrow</td><td>${ico("tractor",46)} barn</td></tr>
     <tr><th>C</th><td>${ico("drop",46)} pond</td><td>${ico("truck",46)} wagon track</td><td>${ico("hen",46)} hen house</td></tr></table>
     <p class="big">${ico("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the scarecrow is in, using its letter and its number.","What is directly north of the scarecrow?","Is the pond east or west of the hen house?","Which square is between the pumpkin patch and the barn?"],key:["B2","the walnut trees, in square A2","west. The pond is in C1 and the hen house is in C3, so the pond is to the left, which is west.","B2, the scarecrow"]}]},{id:28,title:"Rules, Money and the Pumpkin Stand",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes rules at each level here, and how another country chooses a leader differently",html:()=>`<p class="big">The farm follows rules. They come from more than one place.</p>
     <p class="big">A government does three jobs with a law. It makes the law. It carries the law out, which is the job of people like a police officer or an inspector. Somebody is said to have broken a law. A court decides whether they really did. Then it decides what should follow. It may be a fine to pay. It may be the damage to put right. It may be a license taken away.</p>
     <div class="figure">${ico("flag",80)}${ico("books",80)}</div>`,qs:["Who leads a city? A mayor, or a farmer?","A state law says a school bus must stop at every railway crossing. Why would a government make a law like that?","Somebody is said to have broken a law. Who decides whether they really did, and name one thing that can follow if they did."],key:["a mayor","To keep people safe. Any answer about safety counts. Laws are made to protect people.","A court decides. Any one from the page: a fine to pay, having to put the damage right, a license taken away. This is the part of the standard about deciding whether a law was broken and what happens then. (HSS-2.3)"]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount of money, and naming a producer and a consumer",html:()=>`<p class="big">The pumpkin stand price list.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a small pumpkin</td><td>45 cents</td></tr>
     <tr><td>a bag of walnuts</td><td>30 cents</td></tr>
     <tr><td>a jar of jam</td><td>40 cents</td></tr>
     <tr><td>a hay wagon ride round the field</td><td>20 cents</td></tr></table>
     <div class="figure">${ico("pumpkin",72)}${ico("truck",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 70 cents and you want all four. Name what you would buy and what you would have to give up.","The farm grows the pumpkins and you buy one. Which of you is the producer and which is the consumer?"],key:["The hay wagon ride. It is something done for you to enjoy, not a thing you take home.","Any pair or set that comes to 70 cents or less: walnuts and jam is 70 cents, pumpkin and the ride is 65 cents, pumpkin and walnuts is 75 cents and is too much. The giving up is the part to listen for, because a set amount of money means some things get left behind.","The farm is the producer, because it grows the pumpkins. You are the consumer, because you buy and use them."]}]},{id:29,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Louis Pasteur was a scientist in France. In his day people did not know. They did not know why milk went bad. They did not know why wine spoiled. Pasteur looked at them under a microscope. He found tiny living things. They were too small to see. The eye could not see them. They were doing it. He showed something. Heating a liquid and cooling it quickly worked. It killed those tiny living things. So the milk stayed good for much longer. He kept working on the same idea for years. He used it to help farmers. Their animals were getting sick. Today milk is still heated this way. It happens before it reaches a shop. It is named after him.</p>
     <div class="figure">${ico("milk",80)}${ico("thermometer",80)}</div>`,qs:["What did Louis Pasteur find out about why milk goes bad?","Which word fits him best from what you read: patient, careless, or greedy? Say why.","Name one way his work still makes a difference today."],key:["Tiny living things too small to see were doing it, and heating the milk and then cooling it quickly killed them so the milk stayed good longer.","patient. Any reason taken from the text: he kept working on the same idea for years, he looked closely under a microscope instead of guessing.","Milk is still heated the way he showed before it reaches a shop, so it keeps longer and is safer to drink. Accept any answer about milk being safe or lasting longer."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Big Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each big word out loud.",html:()=>`<div style="text-align:center">${["wheelbarrow","uncovered","peacefully"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["wheelbarrow (wheel-bar-row)","uncovered (un-cov-ered)","peacefully (peace-ful-ly)"]},2:{id:"L2",title:"Level Up: Times Rows",std:["3.OA.A.1"],needs:["2.OA.C.4"],n:2,dir:"Write the first answer on your paper and hold it up. Say the second answer out loud.",html:()=>`${F.row(pumpArray(3,6))}<ol class="qlist"><li>This patch has 3 rows of 6 pumpkins. Write it as a times fact and tell how many pumpkins there are.</li><li>Make up a pumpkin patch story for 4 x 5.</li></ol>`,key:["3 x 6 = 18","Tells about 4 groups of 5 things, or 5 groups of 4 (for example: 4 wagons with 5 pumpkins in each wagon). 20 in all."]},4:{id:"L4",title:"Level Up: Round the Seeds",std:["3.NBT.A.1"],needs:["2.NBT.A.1"],n:2,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge">368</p><p class="big" style="text-align:center">A farmer has 368 seeds.</p><ol class="qlist"><li>Round 368 to the nearest ten.</li><li>Round 368 to the nearest hundred.</li></ol>`,key:["370 (368 is between 360 and 370, and it is closer to 370)","400 (368 is between 300 and 400, and it is closer to 400)"]},6:{id:"L6",title:"Level Up: Wagon Trips",std:["3.OA.D.8"],needs:["2.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer and how you got it.",html:()=>`<p class="big">A wagon carries 6 pumpkins on each trip. It makes 3 trips to the barn. Then 4 pumpkins roll out the barn door. How many pumpkins are in the barn now?</p>`,key:["14 pumpkins (3 x 6 = 18, then 18 - 4 = 14)"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let c120On={},blk=[0,0,0],pvVal=["",""],nlStart="",nlHops=[],nlShown={};function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function nlSvg(){if(nlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+nlStart];nlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;nlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+nlStart||nlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+nlStart?"":`data-v="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function nlHtml(){const j=d=>`<button class="chip" data-j="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="nlStart" value="${nlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-j="u">Undo</button><button class="chip" data-j="x">Clear</button></div><div class="tool-scroll" id="nlBox" style="text-align:center">${nlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function nlBind(b,r){const box=()=>b.querySelectorAll("[data-v]").forEach(g=>g.onclick=()=>{nlShown[g.dataset.v]=!nlShown[g.dataset.v];r()});const inp=b.querySelector("#nlStart");inp.oninput=()=>{nlStart=inp.value.replace(/[^0-9]/g,"");nlShown={};b.querySelector("#nlBox").innerHTML=nlSvg();box()};b.querySelectorAll("[data-j]").forEach(x=>x.onclick=()=>{const k=x.dataset.j;if(k==="x"){nlHops=[];nlShown={}}else if(k==="u")nlHops.pop();else if(nlStart!==""&&nlHops.length<10)nlHops.push(+k);r()});box()}const STARTERS={opinion:["I think the ____ pumpkin is the better buy.","One reason is ____.","That is why ____."],story:["One day, ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."],facts:["Fall is ____.","In fall, ____.","Also, ____.","Harvest means ____.","That is why ____."]};const SENTSET={"W.2.1":"opinion","W.2.2":"facts","W.2.3":"story","W.2.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].alt&&parts[0].alt.key;sets.push(STARTERS[k]?k:"story")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}function tpsCoinHtml(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:2,unit:"in",item:4.5,itemLabel:"pencil"}))+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:nlHtml,bind:nlBind},chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},coins:{name:"Coin values",std:["2.MD.C.8"],html:tpsCoinHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"blocks",std:["2.NBT.A.1"],msg:"With the blocks out, Hundreds, Tens, Ones shows the student can read a model. It does not show they know what each digit is worth without one."},{t:"blocks",std:["2.OA.A.1"],msg:"If you built the numbers with blocks for the student, count the word problems as supported, not independent."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count the digit value and expanded form items as supported, not independent."},{t:"nl",msg:"Show a landing number only after the student says it. If you showed it first, the number line did that step for the student."},{t:"chart",std:["2.OA.A.1"],msg:"With the 120 chart the student can count on or back square by square. Note it if the answer came from counting by ones on the chart."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"blocks",std:["2.NBT.B.7"],msg:"Trading ten ones for a ten on the mat is the regrouping itself. If the blocks did that step, note that the written method was supported."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
